namespace BF4Bots {
public static partial class OneClick {
 [DllImport("iphlpapi.dll",SetLastError=true)]static extern uint GetExtendedTcpTable(IntPtr table,ref int size,bool order,int family,int tableClass,uint reserved);
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr window);
 [DllImport("user32.dll")]static extern bool ShowWindowAsync(IntPtr window,int cmd);
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 public static int PortOwner(int port){int size=0;GetExtendedTcpTable(IntPtr.Zero,ref size,false,2,3,0);IntPtr buffer=Marshal.AllocHGlobal(size);try{if(GetExtendedTcpTable(buffer,ref size,false,2,3,0)!=0)throw new IOException("Não consegui consultar as portas locais.");int count=Marshal.ReadInt32(buffer);for(int i=0;i<count;i++){int row=4+i*24;uint raw=unchecked((uint)Marshal.ReadInt32(buffer,row+8));int p=(int)(((raw&255)<<8)|((raw>>8)&255));if(p==port)return Marshal.ReadInt32(buffer,row+20);}return 0;}finally{Marshal.FreeHGlobal(buffer);}}
 public static string ProcessPath(int pid){using(var p=Process.GetProcessById(pid))return Path.GetFullPath(p.MainModule.FileName);}
 public static bool SamePath(string a,string b){return String.Equals(Path.GetFullPath(a),Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);}
 public static List<Process> At(string path){var list=new List<Process>();foreach(var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(path))){try{if(SamePath(p.MainModule.FileName,path))list.Add(p);}catch{throw new UnauthorizedAccessException("É necessário acesso de administrador para conferir os processos locais.");}}return list;}
 public static void Focus(Process p){p.Refresh();if(p.MainWindowHandle!=IntPtr.Zero){ShowWindowAsync(p.MainWindowHandle,9);SetForegroundWindow(p.MainWindowHandle);}}
 static string Value(string text,string key,string fallback){var line=text.Split('\n').FirstOrDefault(l=>l.TrimStart().StartsWith(key+"=",StringComparison.OrdinalIgnoreCase));return line==null?fallback:line.Substring(line.IndexOf('=')+1).Trim();}
 static int Port(string text,string key,int fallback){int n;if(!Int32.TryParse(Value(text,key,fallback.ToString()),out n)||n<1||n>65535)throw new InvalidDataException("Porta inválida: "+key);return n;}
 public static Dictionary<string,object> Request(string url,string method,string body){var uri=new Uri(url);if(uri.Host!="127.0.0.1"||uri.Scheme!="http")throw new InvalidOperationException("A integração aceita somente HTTP local.");var req=(HttpWebRequest)WebRequest.Create(uri);req.Proxy=null;req.Method=method;req.Timeout=5000;req.ReadWriteTimeout=5000;req.AllowAutoRedirect=false;if(body!=null){var bytes=Encoding.UTF8.GetBytes(body);req.ContentType="application/json";req.ContentLength=bytes.Length;using(var s=req.GetRequestStream())s.Write(bytes,0,bytes.Length);}HttpWebResponse response;try{response=(HttpWebResponse)req.GetResponse();}catch(WebException ex){if(ex.Response==null)throw;response=(HttpWebResponse)ex.Response;}using(response)using(var r=new StreamReader(response.GetResponseStream())){string text=r.ReadToEnd();if(text.Length>65536)throw new IOException("Resposta local excessiva.");var obj=Json.Deserialize<Dictionary<string,object>>(text);if(obj==null)throw new InvalidDataException("Resposta local inválida.");if((int)response.StatusCode>=400)throw new InvalidOperationException(obj.ContainsKey("message")?Convert.ToString(obj["message"]):"Falha na API local.");return obj;}}
 public static bool Running(Dictionary<string,object> status){return status.ContainsKey("running")&&status["running"] is bool&&(bool)status["running"];}
 public static string GameCommand(string ip,string extra){IPAddress address;if(!IPAddress.TryParse(ip,out address)||address.AddressFamily!=AddressFamily.InterNetwork)throw new InvalidDataException("Use um endereço IPv4 válido para o backend.");if(extra.IndexOfAny(new[]{'\r','\n','\0'})>=0)throw new InvalidDataException("Argumentos adicionais contêm caracteres inválidos.");if(System.Text.RegularExpressions.Regex.IsMatch(extra,@"(?i)(?:^|\s)-(?:blazeIP|patchSSL)(?:$|[\s=])"))throw new InvalidDataException("Remova -blazeIP e -patchSSL dos argumentos extras; a Central inclui essas opções automaticamente.");return "-blazeIP "+address+" -patchSSL"+(String.IsNullOrWhiteSpace(extra)?"":" "+extra);}
 public static string LaunchBody(string extra){return Json.Serialize(new Dictionary<string,object>{{"commandLine",extra}});}
 static void WaitOwner(int port,string exe,int seconds,Action<string> progress){var watch=Stopwatch.StartNew();while(watch.Elapsed.TotalSeconds<seconds){int pid=PortOwner(port);if(pid!=0){if(!SamePath(ProcessPath(pid),exe))throw new IOException("A porta "+port+" está ocupada por outro programa. Nenhum processo desconhecido foi fechado.");return;}Thread.Sleep(400);}throw new TimeoutException("O componente não abriu a porta "+port+" a tempo. Tente novamente; não será iniciada uma segunda cópia.");}
 static void CloseVerified(Process p,string expected){if(!SamePath(p.MainModule.FileName,expected))throw new IOException("O processo mudou; fechamento cancelado.");p.CloseMainWindow();if(!p.WaitForExit(3000)){p.Kill();if(!p.WaitForExit(6000))throw new IOException("O processo não encerrou.");}}
 static void FreeGamePort(Action<string> progress){int pid=PortOwner(3216);if(pid==0)return;string owner=ProcessPath(pid);string ea=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Electronic Arts\\EA Desktop\\EA Desktop\\EADesktop.exe");if(!SamePath(owner,ea))throw new IOException("A porta 3216 está ocupada por "+Path.GetFileName(owner)+". Não vou encerrar um programa desconhecido.");progress("Fechando o EA App que ocupa a porta do jogo offline…");using(var p=Process.GetProcessById(pid))CloseVerified(p,ea);var w=Stopwatch.StartNew();while(w.Elapsed.TotalSeconds<8){if(PortOwner(3216)==0)return;Thread.Sleep(300);}throw new IOException("O EA App voltou a ocupar a porta 3216. Feche-o e tente novamente.");}
 static void Ensure(string exe,int port,Action start,Action<string> progress,int timeout){int owner=PortOwner(port);var found=At(exe);if(owner!=0){if(!SamePath(ProcessPath(owner),exe))throw new IOException("Porta "+port+" ocupada por "+Path.GetFileName(ProcessPath(owner))+".");foreach(var p in found.Where(p=>p.Id!=owner))CloseVerified(p,exe);return;}if(found.Count==0)start();else if(found.Count>1)throw new IOException("Há cópias do componente ainda carregando. Não iniciei outra. Aguarde e tente novamente.");WaitOwner(port,exe,timeout,progress);}
 public static string Run(string root,Action<string> progress){string lockName="Local\\BF4BotLauncher_Start_"+Config.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(root).ToLowerInvariant())).Substring(0,16);using(var mutex=new Mutex(false,lockName)){bool locked=false;try{try{locked=mutex.WaitOne(0);}catch(AbandonedMutexException){locked=true;}if(!locked)throw new InvalidOperationException("A inicialização já está em andamento em outra janela.");Config.ValidateRoot(root);string game=Path.Combine(root,"bf4_no_drm.exe"),launcher=Path.Combine(root,"BF4Launcher.exe"),backend=Path.Combine(root,"Server\\BF4BlazeServer.exe"),server=Path.Combine(root,"Server\\bf4_Server_Final.exe");var games=At(game);if(games.Count>0){PrepareLocal(root,progress);var existing=Settings.Read(root);if(Settings.Get(existing,"BlazeIP","127.0.0.1")=="127.0.0.1"&&!HasBackend(games[0].Id,10040))throw new IOException("O jogo aberto não está conectado ao backend offline. Feche o BF4 e clique em Iniciar tudo e jogar para iniciar com os parâmetros locais corretos.");Focus(games[0]);return "Jogo aberto e conexão TCP com o backend offline confirmada. Abra o navegador de servidores no jogo.";}
 string cfg=File.ReadAllText(Path.Combine(root,"config.txt"));bool local=Value(cfg,"BlazeIP","127.0.0.1")=="127.0.0.1";int rcon=Port(cfg,"RconPort",25210);string backendCfg=File.ReadAllText(Path.Combine(root,"Server\\config.txt"));int backendPort=Port(backendCfg,"ClientPort",10040);
 progress("Verificando conflito da porta 3216 e componentes abertos…");int lsx=PortOwner(3216);if(lsx!=0&&SamePath(ProcessPath(lsx),launcher)){var status=Request("http://127.0.0.1:42190/status","GET",null);if(Running(status))progress("Verificando a sessão do jogo já iniciada…");}else FreeGamePort(progress);
 if(local){progress("Preparando backend local…");Ensure(backend,backendPort,()=>Process.Start(new ProcessStartInfo(backend){WorkingDirectory=Path.Combine(root,"Server"),UseShellExecute=true,WindowStyle=ProcessWindowStyle.Hidden}),progress,30);
 progress("Preparando servidor local e removendo cópias duplicadas desta instalação…");Ensure(server,rcon,()=>Server.Start(root,null),progress,90);}
 progress("Preparando o launcher original…");foreach(int port in new[]{32170,42190}){int pid=PortOwner(port);if(pid!=0&&!SamePath(ProcessPath(pid),launcher))throw new IOException("A porta "+port+" está ocupada por outro programa.");}
 var launchers=At(launcher);if(launchers.Count>1)throw new IOException("Há mais de um launcher original aberto. Não iniciei outra cópia.");if(launchers.Count==0)Process.Start(new ProcessStartInfo(launcher){WorkingDirectory=root,UseShellExecute=true,WindowStyle=ProcessWindowStyle.Minimized});WaitOwner(32170,launcher,30,progress);WaitOwner(42190,launcher,30,progress);
 var health=Request("http://127.0.0.1:32170/health","GET",null);if(!health.ContainsKey("service")||Convert.ToString(health["service"])!="launch")throw new IOException("A API local não corresponde ao launcher esperado.");var state=Request("http://127.0.0.1:42190/status","GET",null);if(!Running(state)){progress("Abrindo o Battlefield 4…");var reply=Request("http://127.0.0.1:32170/launch","POST",LaunchBody(GameCommand(Value(cfg,"BlazeIP","127.0.0.1"),Value(cfg,"ExtraArguments",""))));if(reply.ContainsKey("success")&&reply["success"] is bool&&!(bool)reply["success"])throw new IOException("O launcher recusou o início do jogo.");}
 var timer=Stopwatch.StartNew();while(timer.Elapsed.TotalSeconds<25){state=Request("http://127.0.0.1:42190/status","GET",null);if(Running(state)){var opened=At(game);if(opened.Count>0){if(local){progress("Aguardando o jogo estabelecer a conexão com o backend offline…");WaitBackend(opened[0].Id,backendPort,45);}Focus(opened[0]);return local?"Jogo conectado ao backend offline local. Abra o navegador de servidores no multiplayer.":"Jogo aberto com os parâmetros do backend configurado.";}}if(state.ContainsKey("state")&&Convert.ToString(state["state"])=="failed")throw new IOException(state.ContainsKey("error")?Convert.ToString(state["error"]):"O jogo não iniciou.");Thread.Sleep(500);}throw new TimeoutException("O launcher recebeu o pedido, mas não confirmou o jogo a tempo. Não repeti a chamada para evitar duplicação.");
 }finally{if(locked)mutex.ReleaseMutex();}}}
 public static int Test(string report){var lines=new List<string>();try{var body=Json.Deserialize<Dictionary<string,object>>(LaunchBody("-x \"dois termos\""));if(body.Count!=1||!body.ContainsKey("commandLine")||Convert.ToString(body["commandLine"])!="-x \"dois termos\"")throw new Exception("Contrato de launch inválido");lines.Add("PASS JSON contém exatamente commandLine e preserva aspas");if(GameCommand("127.0.0.1","")!="-blazeIP 127.0.0.1 -patchSSL")throw new Exception("Faltam parâmetros offline");if(GameCommand("127.0.0.1","-x \"dois termos\"")!="-blazeIP 127.0.0.1 -patchSSL -x \"dois termos\"")throw new Exception("Argumentos extras alterados");bool invalid=false;try{GameCommand("127.0.0.1","-blazeIP 8.8.8.8");}catch(InvalidDataException){invalid=true;}if(!invalid)throw new Exception("Aceitou parâmetros conflitantes");lines.Add("PASS parâmetros offline obrigatórios, extras e bloqueio de conflito");if(!Running(new Dictionary<string,object>{{"running",true}})||Running(new Dictionary<string,object>{{"running",false}})||Running(new Dictionary<string,object>()))throw new Exception("Detecção de jogo inválida");lines.Add("PASS jogo aberto/fechado e estado ausente");if(!SamePath("C:\\Windows\\explorer.exe","c:\\windows\\EXPLORER.EXE")||SamePath("C:\\a.exe","C:\\b.exe"))throw new Exception("Comparação de processos inválida");lines.Add("PASS verificação de caminhos de processos");int owner=PortOwner(32170);if(owner!=0)lines.Add("PASS consulta de dono da porta local: PID "+owner);File.WriteAllLines(report,lines,Encoding.UTF8);return 0;}catch(Exception ex){lines.Add("FAIL "+ex);File.WriteAllLines(report,lines,Encoding.UTF8);return 1;}}
}
